from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urlsplit,unquote
class Page(HTMLParser):
 def __init__(self): super().__init__(); self.ids=set();self.anchors=[];self.imgs=[];self.a=None;self.text=[]
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'id' in a:self.ids.add(a['id'])
  if tag=='a':self.a=[a.get('href',''),'']
  if tag=='img':self.imgs.append(a)
 def handle_data(self,d):
  if self.a is not None:self.a[1]+=d
 def handle_endtag(self,tag):
  if tag=='a' and self.a is not None:self.anchors.append(self.a);self.a=None
p=Page();p.feed(Path('rendered/extraction-integration-rejection.html').read_text())
print('local section/figure links:')
for href,label in p.anchors:
 if href.startswith('#') and (href[1:].startswith(('sec-','fig-'))):print(href,'target exists',unquote(href[1:]) in p.ids,'label',' '.join(label.split()))
print('chapter navigation and prerequisite links:')
for href,label in p.anchors:
 if href.endswith('.html') and label.strip():print(href,'|',' '.join(label.split()))
print('figure image references:')
for a in p.imgs:
 src=a.get('src',''); print(src,'packet file exists',(Path('book')/src).is_file(),'alt present',bool(a.get('alt')))
print('screenshot dimensions:')
import struct
for f in sorted(Path('images').glob('*.png')):
 data=f.read_bytes();print(f.name,struct.unpack('>II',data[16:24]))
